import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment } from '../types';
import { INITIAL_WAREHOUSES, INITIAL_LOCATIONS, INITIAL_TRANSFERS, INITIAL_COUNTS, INITIAL_RESERVATIONS, INITIAL_RECEIPTS, INITIAL_ADJUSTMENTS } from '../services/data';

interface StockState {
  warehouses: Warehouse[];
  locations: StorageLocation[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];

  addWarehouse: (w: Warehouse) => void;
  updateWarehouse: (w: Warehouse) => void;
  deleteWarehouse: (id: string) => void;

  addLocation: (l: StorageLocation) => void;
  updateLocation: (l: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  // Generic Update Helpers for Docs (simplifies boilerplate)
  updateDocument: (type: 'transfers' | 'counts' | 'reservations' | 'receipts' | 'adjustments', doc: any) => void;
  deleteDocument: (type: 'transfers' | 'counts' | 'reservations' | 'receipts' | 'adjustments', id: string) => void;

  restoreStockData: (data: any) => void;
}

export const useStockStore = create<StockState>()(
  persist(
    (set) => ({
      warehouses: INITIAL_WAREHOUSES,
      locations: INITIAL_LOCATIONS,
      transfers: INITIAL_TRANSFERS,
      counts: INITIAL_COUNTS,
      reservations: INITIAL_RESERVATIONS,
      receipts: INITIAL_RECEIPTS,
      adjustments: INITIAL_ADJUSTMENTS,

      addWarehouse: (w) => set((state) => ({ warehouses: [...state.warehouses, w] })),
      updateWarehouse: (w) => set((state) => ({ warehouses: state.warehouses.map(x => x.id === w.id ? w : x) })),
      deleteWarehouse: (id) => set((state) => ({ warehouses: state.warehouses.filter(x => x.id !== id) })),

      addLocation: (l) => set((state) => ({ locations: [...state.locations, l] })),
      updateLocation: (l) => set((state) => ({ locations: state.locations.map(x => x.id === l.id ? l : x) })),
      deleteLocation: (id) => set((state) => ({ locations: state.locations.filter(x => x.id !== id) })),

      updateDocument: (type, doc) => set((state) => {
        const list = state[type] as any[];
        const exists = list.some(x => x.id === doc.id);
        const newList = exists ? list.map(x => x.id === doc.id ? doc : x) : [doc, ...list];
        return { [type]: newList } as any;
      }),

      deleteDocument: (type, id) => set((state) => {
        const list = state[type] as any[];
        return { [type]: list.filter(x => x.id !== id) } as any;
      }),

      restoreStockData: (data) => set((state) => ({
        ...state,
        warehouses: data.warehouses || state.warehouses,
        locations: data.locations || state.locations,
        transfers: data.transfers || state.transfers,
        counts: data.counts || state.counts,
        reservations: data.reservations || state.reservations,
        receipts: data.receipts || state.receipts,
        adjustments: data.adjustments || state.adjustments
      }))
    }),
    {
      name: 'bm_stock_store',
    }
  )
);

import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  Product, Sale, UnitDefinition, CategoryItem, Branch, PosMachine, Warehouse, 
  StorageLocation, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  User, SystemSettings, SyncLog, Customer, CustomerLevel, Shift, ShiftSchedule, Promotion, 
  CartItem, DocumentStatus, AppNotification, AuditLog, AuditAction
} from '../types';
import { translations } from '../services/translations';

// Import Zustand Stores
import { useSystemStore } from '../store/useSystemStore';
import { useInventoryStore } from '../store/useInventoryStore';
import { useSalesStore } from '../store/useSalesStore';
import { useStockStore } from '../store/useStockStore';

interface GlobalContextType {
  currentUser: User | null;
  setCurrentUser: (user: User | null) => void;
  users: User[];
  products: Product[];
  sales: Sale[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  branches: Branch[];
  posMachines: PosMachine[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  syncLogs: SyncLog[];
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];
  promotions: Promotion[];
  settings: SystemSettings;
  isLoading: boolean;
  notifications: AppNotification[];
  auditLogs: AuditLog[];

  processSale: (items: CartItem[], total: number, customerId?: string, discountAmount?: number, subtotal?: number, paymentMethod?: any, amountReceived?: number, change?: number, pointsRedeemed?: number) => Promise<Sale>;
  processReturn: (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], paymentMethod: string) => Promise<Sale>;

  addProduct: (p: Product) => void;
  updateProduct: (p: Product) => void;
  deleteProduct: (id: string) => void;

  addUnit: (u: UnitDefinition) => void;
  updateUnit: (u: UnitDefinition) => void;
  deleteUnit: (id: string) => void;

  addCategory: (c: CategoryItem) => void;
  updateCategory: (c: CategoryItem) => void;
  deleteCategory: (id: string) => void;

  addBranch: (b: Branch) => void;
  updateBranch: (b: Branch) => void;
  deleteBranch: (id: string) => void;

  addPos: (p: PosMachine) => void;
  updatePos: (p: PosMachine) => void;
  deletePos: (id: string) => void;

  addWarehouse: (w: Warehouse) => void;
  updateWarehouse: (w: Warehouse) => void;
  deleteWarehouse: (id: string) => void;

  addLocation: (l: StorageLocation) => void;
  updateLocation: (l: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  addUser: (u: User) => void;
  updateUser: (u: User) => void;
  deleteUser: (id: string) => void;

  addCustomer: (c: Customer) => void;
  updateCustomer: (c: Customer) => void;
  deleteCustomer: (id: string) => void;
  addCustomerLevel: (l: CustomerLevel) => void;
  updateCustomerLevel: (l: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;

  updateTransfer: (t: StockTransfer) => void;
  deleteTransfer: (id: string) => void;

  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;

  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;

  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;

  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;

  startShift: (branchId: string, startCash: number, notes?: string) => void;
  endShift: (shiftId: string, endCash: number, notes?: string) => void;
  addShiftSchedule: (s: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  addPromotion: (p: Promotion) => void;
  updatePromotion: (p: Promotion) => void;
  deletePromotion: (id: string) => void;

  updateSettings: (s: SystemSettings) => void;

  settleSaleDebt: (saleId: string, amount: number, method: string) => Promise<void>;
  handleVoidSale: (saleId: string) => void;

  t: (key: string) => string;
  formatPrice: (amount: number) => string;

  addNotification: (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => void;
  markNotificationRead: (id: string) => void;
  clearAllNotifications: () => void;

  restoreSystemData: (data: any) => void;
  logAction: (action: AuditAction, details: string, severity?: 'low' | 'medium' | 'high' | 'critical', resourceId?: string) => void;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Zustand Store Connections ---
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  const [isLoading, setIsLoading] = useState(true);

  // Initialize
  useEffect(() => {
    // Simulate loading time for hydration if needed
    const timer = setTimeout(() => setIsLoading(false), 300);
    return () => clearTimeout(timer);
  }, []);

  // --- Derived Actions (Orchestration) ---

  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[systemStore.settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = systemStore.settings.currencySymbol || '$';
    return `${symbol}${Math.abs(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  // Complex business logic that spans multiple stores
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    let pointsEarned = 0;
    if (systemStore.settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = systemStore.settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items, total, subtotal, discountAmount,
      date: new Date().toISOString(),
      paymentMethod, amountReceived, change, customerId,
      customerName: customerId ? salesStore.customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending',
      pointsRedeemed,
      pointsEarned,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      type: 'sale'
    };

    // 1. Add Sale
    salesStore.addSale(newSale);

    // 2. Deduct Inventory
    items.forEach(item => {
      // Simple logic: deduct quantity from global stock
      inventoryStore.updateProductStock(item.id, -item.quantity);
    });

    // 3. Update Customer Points
    if (customerId) {
      const customer = salesStore.customers.find(c => c.id === customerId);
      if (customer) {
        salesStore.updateCustomer({
          ...customer,
          loyaltyPoints: Math.max(0, (customer.loyaltyPoints || 0) - pointsRedeemed + pointsEarned)
        });
      }
    }

    return newSale;
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], paymentMethod: string): Promise<Sale> => {
    let refundTotal = 0;
    const returnedItems: CartItem[] = [];

    itemsToReturn.forEach(({ itemIndex, quantity }) => {
      const originalItem = originalSale.items[itemIndex];
      if (originalItem && quantity > 0) {
        refundTotal += originalItem.sellPrice * quantity;
        returnedItems.push({ ...originalItem, quantity });
      }
    });

    const refundSale: Sale = {
      id: `R-${Date.now()}`,
      originalSaleId: originalSale.id,
      items: returnedItems,
      total: -refundTotal,
      subtotal: -refundTotal,
      discountAmount: 0,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod as any,
      paymentStatus: 'paid',
      amountReceived: -refundTotal,
      change: 0,
      remainingAmount: 0,
      status: 'completed',
      syncStatus: 'pending',
      customerId: originalSale.customerId,
      customerName: originalSale.customerName,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      type: 'return'
    };

    salesStore.addSale(refundSale);

    // Restore Inventory
    returnedItems.forEach(item => {
      inventoryStore.updateProductStock(item.id, item.quantity);
    });

    systemStore.logAction({
      id: `log-${Date.now()}`,
      action: 'SALE_RETURN',
      details: `Processed refund for Sale #${originalSale.id}`,
      severity: 'medium',
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString(),
      resourceId: refundSale.id
    });

    return refundSale;
  };

  const handleVoidSale = async (saleId: string) => {
     const saleToVoid = salesStore.sales.find(s => s.id === saleId);
     if (saleToVoid) {
        salesStore.updateSale({ ...saleToVoid, status: 'voided' });

        // Restore stock
        saleToVoid.items.forEach(item => {
           inventoryStore.updateProductStock(item.id, item.quantity);
        });

        systemStore.logAction({
          id: `log-${Date.now()}`,
          action: 'SALE_VOID',
          details: `Voided sale ${saleId}`,
          severity: 'high',
          userId: systemStore.currentUser?.id || 'sys',
          userName: systemStore.currentUser?.name || 'System',
          timestamp: new Date().toISOString(),
          resourceId: saleId
        });
     }
  };

  const handleStockStatusChange = (
    type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', 
    id: string, 
    status: DocumentStatus
  ) => {
    // 1. Update Document Status
    const doc = (stockStore[type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments'] as any[]).find(x => x.id === id);
    if (!doc) return;

    if (type === 'transfer') stockStore.updateDocument('transfers', { ...doc, status });
    else if (type === 'count') stockStore.updateDocument('counts', { ...doc, status });
    else if (type === 'reservation') stockStore.updateDocument('reservations', { ...doc, status });
    else if (type === 'receipt') stockStore.updateDocument('receipts', { ...doc, status });
    else if (type === 'adjustment') stockStore.updateDocument('adjustments', { ...doc, status });

    // 2. Execute Inventory Updates if Completed
    if (status === 'Completed' && doc.status !== 'Completed') {
       if (type === 'receipt') {
          doc.items.forEach((item: any) => {
             inventoryStore.updateProductStock(item.productId, item.quantity);
          });
       } else if (type === 'adjustment') {
          doc.items.forEach((item: any) => {
             inventoryStore.updateProductStock(item.productId, item.quantity); // Signed quantity
          });
       } else if (type === 'count') {
          doc.items.forEach((item: any) => {
             if (item.diff !== undefined) {
               inventoryStore.updateProductStock(item.productId, item.diff); // Diff applied
             }
          });
       }
       // Note: Transfer logic assumes multi-warehouse which is simplified here to global stock for the demo context.
       // In a full implementation, `updateProductStock` would take a warehouseId.
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!systemStore.currentUser) return;
    salesStore.startShift({
      id: `sh-${Date.now()}`,
      userId: systemStore.currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    });
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    salesStore.endShift(shiftId, {
      endTime: new Date().toISOString(),
      endCash,
      notes,
      status: 'Closed'
    });
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     systemStore.addSyncLog({
        id: `sync-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: 'Simulated sync completed successfully.',
        durationMs: Math.floor(Math.random() * 1000) + 200
     });
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     const sale = salesStore.sales.find(s => s.id === saleId);
     if (sale) {
       salesStore.updateSale({
          ...sale,
          paymentStatus: 'paid',
          remainingAmount: 0,
          amountReceived: (sale.amountReceived || 0) + amount
       });
     }
  };

  // Automated Notification Logic (Example: Low Stock)
  useEffect(() => {
    const lowStockItems = inventoryStore.products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       const hasUnread = systemStore.notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          systemStore.addNotification({
             id: `notif-stock-${Date.now()}`,
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory',
             timestamp: new Date().toISOString(),
             read: false
          });
       }
    }
  }, [inventoryStore.products.length, systemStore.notifications.length]);

  const restoreSystemData = (data: any) => {
    systemStore.restoreSystemData(data);
    inventoryStore.restoreInventoryData(data);
    salesStore.restoreSalesData(data);
    stockStore.restoreStockData(data);
    systemStore.logAction({
      id: `aud-${Date.now()}`,
      action: 'SETTINGS_UPDATE',
      details: 'System data restored from backup',
      severity: 'high',
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString()
    });
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
    systemStore.addNotification({
      ...n,
      id: `notif-${Date.now()}`,
      timestamp: new Date().toISOString(),
      read: false
    });
  };

  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    systemStore.logAction({
      id: `aud-${Date.now()}`,
      action,
      details,
      severity,
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString(),
      resourceId
    });
  };

  // --- Exposed Value ---
  // Note: This matches the original interface so consumers don't break,
  // but it proxies to the granular stores.
  const value: GlobalContextType = {
    // System
    currentUser: systemStore.currentUser,
    setCurrentUser: systemStore.setCurrentUser,
    users: systemStore.users,
    settings: systemStore.settings,
    branches: systemStore.branches,
    posMachines: systemStore.posMachines,
    auditLogs: systemStore.auditLogs,
    syncLogs: systemStore.syncLogs,
    notifications: systemStore.notifications,

    // Inventory
    products: inventoryStore.products,
    units: inventoryStore.units,
    categories: inventoryStore.categories,

    // Sales
    sales: salesStore.sales,
    customers: salesStore.customers,
    customerLevels: salesStore.customerLevels,
    shifts: salesStore.shifts,
    shiftSchedules: salesStore.shiftSchedules,
    promotions: salesStore.promotions,

    // Stock
    warehouses: stockStore.warehouses,
    locations: stockStore.locations,
    transfers: stockStore.transfers,
    counts: stockStore.counts,
    reservations: stockStore.reservations,
    receipts: stockStore.receipts,
    adjustments: stockStore.adjustments,

    isLoading,

    // Actions
    processSale,
    processReturn,

    addProduct: inventoryStore.addProduct,
    updateProduct: inventoryStore.updateProduct,
    deleteProduct: inventoryStore.deleteProduct,

    addUnit: inventoryStore.addUnit,
    updateUnit: inventoryStore.updateUnit,
    deleteUnit: inventoryStore.deleteUnit,

    addCategory: inventoryStore.addCategory,
    updateCategory: inventoryStore.updateCategory,
    deleteCategory: inventoryStore.deleteCategory,

    addBranch: systemStore.addBranch,
    updateBranch: systemStore.updateBranch,
    deleteBranch: systemStore.deleteBranch,

    addPos: systemStore.addPos,
    updatePos: systemStore.updatePos,
    deletePos: systemStore.deletePos,

    addWarehouse: stockStore.addWarehouse,
    updateWarehouse: stockStore.updateWarehouse,
    deleteWarehouse: stockStore.deleteWarehouse,

    addLocation: stockStore.addLocation,
    updateLocation: stockStore.updateLocation,
    deleteLocation: stockStore.deleteLocation,

    addUser: systemStore.addUser,
    updateUser: systemStore.updateUser,
    deleteUser: systemStore.deleteUser,

    addCustomer: salesStore.addCustomer,
    updateCustomer: salesStore.updateCustomer,
    deleteCustomer: salesStore.deleteCustomer,
    addCustomerLevel: salesStore.addCustomerLevel,
    updateCustomerLevel: salesStore.updateCustomerLevel,
    deleteCustomerLevel: salesStore.deleteCustomerLevel,

    updateTransfer: (t) => stockStore.updateDocument('transfers', t),
    deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),

    updateCount: (c) => stockStore.updateDocument('counts', c),
    deleteCount: (id) => stockStore.deleteDocument('counts', id),

    updateReservation: (r) => stockStore.updateDocument('reservations', r),
    deleteReservation: (id) => stockStore.deleteDocument('reservations', id),

    updateReceipt: (r) => stockStore.updateDocument('receipts', r),
    deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),

    updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
    deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),

    handleStockStatusChange,
    handleSyncOperation,

    startShift,
    endShift,
    addShiftSchedule: salesStore.addShiftSchedule,
    deleteShiftSchedule: salesStore.deleteShiftSchedule,

    addPromotion: salesStore.addPromotion,
    updatePromotion: salesStore.updatePromotion,
    deletePromotion: salesStore.deletePromotion,

    updateSettings: systemStore.updateSettings,

    settleSaleDebt,
    handleVoidSale,

    t,
    formatPrice,

    addNotification,
    markNotificationRead: systemStore.markNotificationRead,
    clearAllNotifications: systemStore.clearAllNotifications,

    restoreSystemData,
    logAction
  };

  return (
    <GlobalContext.Provider value={value}>
      {children}
    </GlobalContext.Provider>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, Warehouse, InventoryAnalysisResult, Sale, Branch } from '../types';
import { Search, Plus, Edit2, Trash2, X, Check, Layers, Box, ArrowRight, ArrowLeftRight, RefreshCw, Info, Building2, AlertTriangle, Bell, Sparkles, Loader2, TrendingUp, AlertCircle, PackagePlus, Scale, DollarSign, Store, ChevronLeft, ChevronRight, ShoppingBag, Image as ImageIcon, Upload, Palette, Ruler, ScanBarcode, Printer, Tag, Download, FileSpreadsheet } from 'lucide-react';
import { analyzeInventory } from '../services/geminiService';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
// Direct Store Access
import { useInventoryStore } from '../store/useInventoryStore';

interface InventoryProps {
  // Keeping props for compatibility if passed from parent, but prioritizing internal store if available
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const Inventory: React.FC<InventoryProps> = ({ 
  // We accept props but also use the store directly for optimized updates
  warehouses = [], 
  sales 
}) => {
  const { settings, t } = useGlobal();

  // Use specific selectors to avoid re-rendering on unrelated changes
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = settings.defaultItemsPerPage || 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<InventoryAnalysisResult | null>(null);

  // Scanner State
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  // Label Printing State
  const [isLabelModalOpen, setIsLabelModalOpen] = useState(false);
  const [labelProduct, setLabelProduct] = useState<Product | null>(null);
  const [labelSettings, setLabelSettings] = useState({
     type: 'shelf' as 'shelf' | 'sticker',
     quantity: 1,
     showPrice: true,
     showSku: true,
     showUnit: true
  });

  // Import State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importPreview, setImportPreview] = useState<any[]>([]);
  const [importStats, setImportStats] = useState({ new: 0, update: 0, error: 0 });
  const importFileRef = useRef<HTMLInputElement>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    sku: '',
    barcode: '',
    category: '',
    price: 0,
    costPrice: 0,
    stock: 0,
    minStock: 20,
    unit: '',
    physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [],
    imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  const getFlattenedCategories = () => {
    const options: { id: string; name: string; level: number }[] = [];
    const buildOptions = (parentId: string | null, level: number) => {
      const children = categories.filter(c => c.parentId === parentId);
      children.forEach(c => {
        options.push({ id: c.id, name: c.name, level });
        buildOptions(c.id, level + 1);
      });
    };
    buildOptions(null, 0);
    return options;
  };

  const categoryOptions = getFlattenedCategories();

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower) ||
      (p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      ));

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setActiveTab('general');
    setFormData({
      name: '',
      sku: '',
      barcode: '',
      category: categoryOptions[0]?.id || '',
      price: 0,
      costPrice: 0,
      stock: 0,
      minStock: 20,
      unit: units[0]?.symbol || 'pc',
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (product: Product) => {
    setEditingId(product.id);
    setActiveTab('general');
    setFormData({
      name: product.name,
      sku: product.sku,
      barcode: product.barcode,
      category: product.category,
      price: product.price,
      costPrice: product.costPrice || 0,
      stock: product.stock,
      minStock: product.minStock || 20,
      unit: product.unit,
      physical: product.physical || { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: product.branchPrices || [],
      imageUrl: product.imageUrl || ''
    });
    setVariants(product.variants ? product.variants.map(v => ({...v})) : []);
    setIsModalOpen(true);
  };

  const handleOpenLabelModal = (product: Product) => {
     setLabelProduct(product);
     setLabelSettings({
        type: 'shelf',
        quantity: 1,
        showPrice: true,
        showSku: true,
        showUnit: true
     });
     setIsLabelModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  useEffect(() => {
    if (isAiModalOpen && !aiResult && !aiLoading) {
      const performAnalysis = async () => {
        setAiLoading(true);
        const result = await analyzeInventory(products, sales);
        setAiResult(result);
        setAiLoading(false);
      };
      performAnalysis();
    }
  }, [isAiModalOpen, products, sales, aiResult, aiLoading]);

  const handleOpenAiInsights = () => setIsAiModalOpen(true);

  // ... (handleInputChange, handlePhysicalChange, variants logic remain same)
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({
      ...prev,
      [name]: isNum ? (parseFloat(value) || 0) : value
    }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      physical: {
        ...prev.physical,
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const generateVariantCodes = (index: number) => {
    const suffix = (index + 1).toString().padStart(3, '0');
    const skuBase = formData.sku || 'SKU';
    return { code: `${skuBase}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '' };
  };

  const handleAddVariant = () => {
    const { code, barcode } = generateVariantCodes(variants.length);
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', 
      code,
      barcode,
      conversionFactor: 1, 
      price: formData.price,
      costPrice: formData.costPrice,
      color: '',
      size: ''
    }]);
  };

  const handleRemoveVariant = (index: number) => setVariants(prev => prev.filter((_, i) => i !== index));

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVariants = [...prev];
      let updatedVariant = { ...newVariants[index], [field]: value };

      if (field === 'name') {
        const mainUnitDef = units.find(u => u.symbol === formData.unit);
        const variantUnitDef = units.find(u => u.symbol === value);
        if (mainUnitDef && variantUnitDef && mainUnitDef.category === variantUnitDef.category) {
          const factor = mainUnitDef.baseFactor / variantUnitDef.baseFactor;
          updatedVariant.conversionFactor = factor;
          updatedVariant.price = (formData.price || 0) / factor;
          updatedVariant.costPrice = (formData.costPrice || 0) / factor;
        }
      }
      if (field === 'price' || field === 'costPrice' || field === 'conversionFactor') {
        updatedVariant[field] = parseFloat(value) || 0;
      }
      newVariants[index] = updatedVariant;
      return newVariants;
    });
  };

  const handleVariantRelationChange = (index: number, ratio: number, mode: 'sub' | 'bundle') => {
    const factor = mode === 'sub' ? ratio : (1 / ratio);
    setVariants(prev => {
      const newVariants = [...prev];
      newVariants[index] = { 
        ...newVariants[index], 
        conversionFactor: factor,
        price: factor !== 0 ? ((formData.price || 0) / factor) : 0,
        costPrice: factor !== 0 ? ((formData.costPrice || 0) / factor) : 0
      };
      return newVariants;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        id: editingId || `P-${Date.now()}`,
        name: formData.name!,
        category: formData.category || 'Uncategorized',
        price: formData.price || 0,
        costPrice: formData.costPrice || 0,
        stock: formData.stock || 0,
        minStock: formData.minStock || 20,
        unit: formData.unit!,
        sku: formData.sku || '',
        barcode: formData.barcode || '',
        physical: formData.physical,
        branchPrices: formData.branchPrices,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: editingId 
          ? products.find(p => p.id === editingId)?.warehouseInventory 
          : [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
        imageUrl: formData.imageUrl
      };

      if (editingId) updateProduct(productData);
      else addProduct(productData);
      setIsModalOpen(false);
    }
  };

  const handleScan = (code: string) => {
    setSearchTerm(code);
    setIsScannerOpen(false);
  };

  const handlePrintLabel = () => {
     window.print();
  };

  // --- CSV Export Logic ---
  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'CostPrice', 'Stock', 'MinStock', 'Unit', 'SKU', 'Barcode'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => {
        const catName = getCategoryName(p.category);
        // Escape quotes for CSV safety
        const safeName = `"${p.name.replace(/"/g, '""')}"`;
        const safeCat = `"${catName.replace(/"/g, '""')}"`;
        return [
          p.id,
          safeName,
          safeCat,
          p.price,
          p.costPrice || 0,
          p.stock,
          p.minStock,
          p.unit,
          p.sku,
          p.barcode
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `inventory_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- CSV Import Logic ---
  const handleImportClick = () => {
    importFileRef.current?.click();
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      const lines = text.split('\n');
      // Simple CSV parse
      const newProducts: any[] = [];
      let newCount = 0;
      let updateCount = 0;
      let errorCount = 0;

      for (let i = 1; i < lines.length; i++) {
        if (!lines[i].trim()) continue;

        const row = lines[i].match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
        if (!row) { errorCount++; continue; }

        // Map based on assumed order: ID, Name, Category, Price, Cost, Stock, Min, Unit, SKU, Barcode
        const p: any = {};
        p.id = row[0]?.replace(/"/g, ''); // ID
        p.name = row[1]?.replace(/"/g, '');
        p.category = row[2]?.replace(/"/g, ''); 
        p.price = parseFloat(row[3]) || 0;
        p.costPrice = parseFloat(row[4]) || 0;
        p.stock = parseFloat(row[5]) || 0;
        p.minStock = parseFloat(row[6]) || 0;
        p.unit = row[7]?.replace(/"/g, '') || 'pc';
        p.sku = row[8]?.replace(/"/g, '') || '';
        p.barcode = row[9]?.replace(/"/g, '') || '';

        // Check if ID exists to update, else new
        const exists = products.find(prod => prod.id === p.id || prod.sku === p.sku);
        if (exists) {
           p.action = 'Update';
           p.existingId = exists.id;
           updateCount++;
        } else {
           p.action = 'Create';
           newCount++;
        }
        newProducts.push(p);
      }

      setImportPreview(newProducts);
      setImportStats({ new: newCount, update: updateCount, error: errorCount });
      setIsImportModalOpen(true);
      if (importFileRef.current) importFileRef.current.value = ''; // Reset
    };
    reader.readAsText(file);
  };

  const confirmImport = () => {
    importPreview.forEach(p => {
       // Logic to resolve Category Name to ID if possible
       let catId = categories[0]?.id || 'uncategorized';
       const matchCat = categories.find(c => c.name.toLowerCase() === (p.category || '').toLowerCase());
       if (matchCat) catId = matchCat.id;

       const productPayload: Product = {
          id: p.existingId || p.id || `P-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          name: p.name || 'Imported Product',
          category: catId,
          price: p.price,
          costPrice: p.costPrice,
          stock: p.stock,
          minStock: p.minStock,
          unit: p.unit,
