import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { User, SystemSettings, Branch, PosMachine, AuditLog, SyncLog, AppNotification } from '../types';
import { INITIAL_USERS, INITIAL_SETTINGS, INITIAL_BRANCHES, INITIAL_POS_MACHINES, INITIAL_AUDIT_LOGS, INITIAL_SYNC_LOGS } from '../services/data';

interface SystemState {
  currentUser: User | null;
  users: User[];
  settings: SystemSettings;
  branches: Branch[];
  posMachines: PosMachine[];
  auditLogs: AuditLog[];
  syncLogs: SyncLog[];
  notifications: AppNotification[];

  setCurrentUser: (user: User | null) => void;
  addUser: (user: User) => void;
  updateUser: (user: User) => void;
  deleteUser: (id: string) => void;

  updateSettings: (settings: SystemSettings) => void;

  addBranch: (branch: Branch) => void;
  updateBranch: (branch: Branch) => void;
  deleteBranch: (id: string) => void;

  addPos: (pos: PosMachine) => void;
  updatePos: (pos: PosMachine) => void;
  deletePos: (id: string) => void;

  logAction: (log: AuditLog) => void;
  addSyncLog: (log: SyncLog) => void;

  addNotification: (n: AppNotification) => void;
  markNotificationRead: (id: string) => void;
  clearAllNotifications: () => void;

  restoreSystemData: (data: any) => void;
}

export const useSystemStore = create<SystemState>()(
  persist(
    (set) => ({
      currentUser: null,
      users: INITIAL_USERS,
      settings: INITIAL_SETTINGS,
      branches: INITIAL_BRANCHES,
      posMachines: INITIAL_POS_MACHINES,
      auditLogs: INITIAL_AUDIT_LOGS,
      syncLogs: INITIAL_SYNC_LOGS,
      notifications: [],

      setCurrentUser: (user) => set({ currentUser: user }),

      addUser: (user) => set((state) => ({ users: [...state.users, user] })),
      updateUser: (user) => set((state) => ({ users: state.users.map(u => u.id === user.id ? user : u) })),
      deleteUser: (id) => set((state) => ({ users: state.users.filter(u => u.id !== id) })),

      updateSettings: (settings) => set({ settings }),

      addBranch: (branch) => set((state) => ({ branches: [...state.branches, branch] })),
      updateBranch: (branch) => set((state) => ({ branches: state.branches.map(b => b.id === branch.id ? branch : b) })),
      deleteBranch: (id) => set((state) => ({ branches: state.branches.filter(b => b.id !== id) })),

      addPos: (pos) => set((state) => ({ posMachines: [...state.posMachines, pos] })),
      updatePos: (pos) => set((state) => ({ posMachines: state.posMachines.map(p => p.id === pos.id ? pos : p) })),
      deletePos: (id) => set((state) => ({ posMachines: state.posMachines.filter(p => p.id !== id) })),

      logAction: (log) => set((state) => ({ auditLogs: [log, ...state.auditLogs] })),
      addSyncLog: (log) => set((state) => ({ syncLogs: [log, ...state.syncLogs] })),

      addNotification: (n) => set((state) => ({ notifications: [n, ...state.notifications] })),
      markNotificationRead: (id) => set((state) => ({ 
        notifications: state.notifications.map(n => n.id === id ? { ...n, read: true } : n) 
      })),
      clearAllNotifications: () => set({ notifications: [] }),

      restoreSystemData: (data) => set((state) => ({
        ...state,
        users: data.users || state.users,
        settings: data.settings || state.settings,
        branches: data.branches || state.branches,
        posMachines: data.posMachines || state.posMachines,
      }))
    }),
    {
      name: 'bm_system_store',
      partialize: (state) => ({ 
        // Persist everything including currentUser to keep session active on refresh
        currentUser: state.currentUser,
        users: state.users,
        settings: state.settings,
        branches: state.branches,
        posMachines: state.posMachines,
        auditLogs: state.auditLogs,
        syncLogs: state.syncLogs
      })
    }
  )
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { CartItem, Product, HeldOrder, Customer } from '../types';

interface CartState {
  cart: CartItem[];
  heldOrders: HeldOrder[];
  addToCart: (product: Product, qty?: number, variantId?: string) => void;
  removeFromCart: (index: number) => void;
  updateQuantity: (index: number, delta: number) => void;
  setQuantity: (index: number, quantity: number) => void;
  clearCart: () => void;

  // Hold & Recall
  holdCurrentOrder: (customer?: Customer | null, note?: string) => void;
  recallOrder: (orderId: string) => HeldOrder | undefined;
  discardHeldOrder: (orderId: string) => void;

  total: number;
}

// Helper to calculate total
const calcTotal = (items: CartItem[]) => items.reduce((sum, item) => sum + item.sellPrice * item.quantity, 0);

export const useCartStore = create<CartState>()(
  persist(
    (set, get) => ({
      cart: [],
      heldOrders: [], 
      total: 0,

      addToCart: (product, qty = 1, variantId) => {
        set((state) => {
          // Logic to find price/unit based on variant
          let sellPrice = product.price;
          let sellUnit = product.unit;
          let conversion = 1;

          if (variantId && product.variants) {
            const variant = product.variants.find((v) => v.id === variantId);
            if (variant) {
              sellPrice = variant.price;
              sellUnit = variant.name;
              conversion = variant.conversionFactor;
            }
          }

          const existingIndex = state.cart.findIndex(
            (item) => item.id === product.id && item.selectedVariantId === variantId
          );

          let newCart;
          if (existingIndex > -1) {
            newCart = [...state.cart];
            newCart[existingIndex].quantity += qty;
          } else {
            const newItem: CartItem = {
              ...product,
              quantity: qty,
              selectedVariantId: variantId,
              sellPrice,
              sellUnit,
              sellConversionFactor: conversion,
            };
            newCart = [...state.cart, newItem];
          }

          return { cart: newCart, total: calcTotal(newCart) };
        });
      },

      removeFromCart: (index) => {
        set((state) => {
          const newCart = state.cart.filter((_, i) => i !== index);
          return { cart: newCart, total: calcTotal(newCart) };
        });
      },

      updateQuantity: (index, delta) => {
        set((state) => {
          const newCart = state.cart.map((item, i) => {
            if (i === index) {
              const newQty = Math.max(1, item.quantity + delta);
              return { ...item, quantity: newQty };
            }
            return item;
          });
          return { cart: newCart, total: calcTotal(newCart) };
        });
      },

      setQuantity: (index, quantity) => {
        set((state) => {
          const newCart = state.cart.map((item, i) => {
            if (i === index) {
              return { ...item, quantity: Math.max(1, quantity) };
            }
            return item;
          });
          return { cart: newCart, total: calcTotal(newCart) };
        });
      },

      clearCart: () => set({ cart: [], total: 0 }),

      holdCurrentOrder: (customer, note) => {
        set((state) => {
          if (state.cart.length === 0) return state;

          const newHeldOrder: HeldOrder = {
            id: `hold-${Date.now()}`,
            items: [...state.cart],
            customer: customer,
            timestamp: new Date().toISOString(),
            note: note,
            total: state.total
          };

          return {
            heldOrders: [newHeldOrder, ...state.heldOrders],
            cart: [],
            total: 0
          };
        });
      },

      recallOrder: (orderId) => {
        const state = get();
        const orderToRecall = state.heldOrders.find(o => o.id === orderId);

        if (orderToRecall) {
          set({
            // Restore cart
            cart: orderToRecall.items,
            total: orderToRecall.total,
            // Remove from held
            heldOrders: state.heldOrders.filter(o => o.id !== orderId)
          });
          return orderToRecall;
        }
        return undefined;
      },

      discardHeldOrder: (orderId) => {
        set((state) => ({
          heldOrders: state.heldOrders.filter(o => o.id !== orderId)
        }));
      }
    }),
    {
      name: 'bm_cart_store',
    }
  )
);

import { hash, compare, hashSync, compareSync } from 'bcryptjs';

const SALT_ROUNDS = 10;

/**
 * Asynchronously hashes a password.
 */
export async function hashPassword(plain: string): Promise<string> {
  return await hash(plain, SALT_ROUNDS);
}

/**
 * Asynchronously verifies a password against a hash.
 */
export async function verifyPassword(plain: string, hashed: string): Promise<boolean> {
  return await compare(plain, hashed);
}

/**
 * Synchronously hashes a password (useful for client-side stores/seeds).
 */
export function hashPasswordSync(plain: string): string {
  return hashSync(plain, SALT_ROUNDS);
}

/**
 * Synchronously verifies a password (useful for client-side auth).
 */
export function verifyPasswordSync(plain: string, hashed: string): boolean {
  return compareSync(plain, hashed);
}

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname;

  // Only protect API routes
  if (path.startsWith('/api/')) {

    // 1. Skip public/auth routes
    if (path.includes('/auth/login')) {
      return NextResponse.next();
    }

    // 2. Verify Authentication (Cookie Check)
    // In a production app, verify a signed JWT here.
    const userRole = request.cookies.get('user_role')?.value;

    if (!userRole) {
      return NextResponse.json(
        { error: 'Unauthorized: Please login first' },
        { status: 401 }
      );
    }

    // 3. Enforce Role-Based Access Control (RBAC)

    // User Management: Admin Only
    if (path.startsWith('/api/users') && request.method !== 'GET') {
       // Allow GET for Managers to see list, but modify strictly for Admin
       if (userRole !== 'Admin') {
         return NextResponse.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
       }
    }

    // Settings: Admin Only
    if (path.startsWith('/api/settings') && request.method !== 'GET') {
       if (userRole !== 'Admin') {
         return NextResponse.json({ error: 'Forbidden: Admin access required' }, { status: 403 });
       }
    }

    // Stock Approvals: Admin or Manager
    if (path.includes('/approvals')) {
       if (userRole !== 'Admin' && userRole !== 'Manager') {
         return NextResponse.json({ error: 'Forbidden: Manager access required' }, { status: 403 });
       }
    }
  }

  return NextResponse.next();
}

