    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Stats
  const myShifts = shifts.filter(s => s.userId === user.id).sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  const mySales = sales.filter(s => s.userId === user.id);
  const totalSalesValue = mySales.reduce((acc, s) => acc + s.total, 0);
  const branchName = branches.find(b => b.id === user.branchId)?.name || 'Unassigned';

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus({ type: 'idle', message: '' });

    if (passForm.newPassword !== passForm.confirmPassword) {
      setStatus({ type: 'error', message: 'New passwords do not match' });
      return;
    }

    if (passForm.newPassword.length < 6) {
      setStatus({ type: 'error', message: 'Password must be at least 6 characters' });
      return;
    }

    setIsSubmitting(true);

    try {
      // API Call
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          currentPassword: passForm.currentPassword,
          newPassword: passForm.newPassword
        })
      });

      const data = await res.json();

      if (res.ok) {
        setStatus({ type: 'success', message: 'Password changed successfully' });
        setPassForm({ currentPassword: '', newPassword: '', confirmPassword: '' });

        // Optionally update client-side store if you want to keep the hash in sync (though client shouldn't really have the hash)
        // updateUser({ ...user }); 
      } else {
        setStatus({ type: 'error', message: data.error || 'Failed to change password' });
      }
