    const handleKeyDown = (e: KeyboardEvent) => {
      // F1 - Dashboard
      if (e.key === 'F1') {
        e.preventDefault();
        onTabChange('dashboard');
      }
      // F2 - POS
      if (e.key === 'F2') {
        e.preventDefault();
        onTabChange('pos');
      }
      // F3 - Inventory
      if (e.key === 'F3') {
        e.preventDefault();
        onTabChange('inventory');
      }
      // F4 / Ctrl+K / Cmd+K - Focus Search
      if (e.key === 'F4' || ((e.ctrlKey || e.metaKey) && e.key === 'k')) {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
      // Shift + ? - Show Shortcuts
      if (e.shiftKey && e.key === '?') {
        e.preventDefault();
        setShowKeyboardHelp(prev => !prev);
      }
