const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Zustand Store Connections ---
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  const [isLoading, setIsLoading] = useState(true);

  // Initialize
  useEffect(() => {
    // Simulate loading time for hydration if needed
    const timer = setTimeout(() => setIsLoading(false), 300);
    return () => clearTimeout(timer);
  }, []);

  // --- Derived Actions (Orchestration) ---

  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[systemStore.settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = systemStore.settings.currencySymbol || '$';
    return `${symbol}${Math.abs(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  // Complex business logic that spans multiple stores
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    let pointsEarned = 0;
    if (systemStore.settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = systemStore.settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items, total, subtotal, discountAmount,
      date: new Date().toISOString(),
      paymentMethod, amountReceived, change, customerId,
      customerName: customerId ? salesStore.customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending',
      pointsRedeemed,
      pointsEarned,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      type: 'sale'
    };

    // 1. Add Sale
    salesStore.addSale(newSale);

    // 2. Deduct Inventory
    items.forEach(item => {
      // Simple logic: deduct quantity from global stock
      inventoryStore.updateProductStock(item.id, -item.quantity);
    });

    // 3. Update Customer Points
    if (customerId) {
      const customer = salesStore.customers.find(c => c.id === customerId);
      if (customer) {
        salesStore.updateCustomer({
          ...customer,
          loyaltyPoints: Math.max(0, (customer.loyaltyPoints || 0) - pointsRedeemed + pointsEarned)
        });
      }
    }

    return newSale;
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], paymentMethod: string): Promise<Sale> => {
    let refundTotal = 0;
    const returnedItems: CartItem[] = [];

    itemsToReturn.forEach(({ itemIndex, quantity }) => {
      const originalItem = originalSale.items[itemIndex];
      if (originalItem && quantity > 0) {
        refundTotal += originalItem.sellPrice * quantity;
        returnedItems.push({ ...originalItem, quantity });
      }
    });

    const refundSale: Sale = {
      id: `R-${Date.now()}`,
      originalSaleId: originalSale.id,
      items: returnedItems,
      total: -refundTotal,
      subtotal: -refundTotal,
      discountAmount: 0,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod as any,
      paymentStatus: 'paid',
      amountReceived: -refundTotal,
      change: 0,
      remainingAmount: 0,
      status: 'completed',
      syncStatus: 'pending',
      customerId: originalSale.customerId,
      customerName: originalSale.customerName,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      type: 'return'
    };

    salesStore.addSale(refundSale);

    // Restore Inventory
    returnedItems.forEach(item => {
      inventoryStore.updateProductStock(item.id, item.quantity);
    });

    systemStore.logAction({
      id: `log-${Date.now()}`,
      action: 'SALE_RETURN',
      details: `Processed refund for Sale #${originalSale.id}`,
      severity: 'medium',
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString(),
      resourceId: refundSale.id
    });

    return refundSale;
  };

  const handleVoidSale = async (saleId: string) => {
     const saleToVoid = salesStore.sales.find(s => s.id === saleId);
     if (saleToVoid) {
        salesStore.updateSale({ ...saleToVoid, status: 'voided' });

        // Restore stock
        saleToVoid.items.forEach(item => {
           inventoryStore.updateProductStock(item.id, item.quantity);
        });

        systemStore.logAction({
          id: `log-${Date.now()}`,
          action: 'SALE_VOID',
          details: `Voided sale ${saleId}`,
          severity: 'high',
          userId: systemStore.currentUser?.id || 'sys',
          userName: systemStore.currentUser?.name || 'System',
          timestamp: new Date().toISOString(),
          resourceId: saleId
        });
     }
  };

  const handleStockStatusChange = (
    type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', 
    id: string, 
    status: DocumentStatus
  ) => {
    // 1. Update Document Status
    const doc = (stockStore[type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments'] as any[]).find(x => x.id === id);
    if (!doc) return;

    if (type === 'transfer') stockStore.updateDocument('transfers', { ...doc, status });
    else if (type === 'count') stockStore.updateDocument('counts', { ...doc, status });
    else if (type === 'reservation') stockStore.updateDocument('reservations', { ...doc, status });
    else if (type === 'receipt') stockStore.updateDocument('receipts', { ...doc, status });
    else if (type === 'adjustment') stockStore.updateDocument('adjustments', { ...doc, status });

    // 2. Execute Inventory Updates if Completed
    if (status === 'Completed' && doc.status !== 'Completed') {
       if (type === 'receipt') {
          doc.items.forEach((item: any) => {
             inventoryStore.updateProductStock(item.productId, item.quantity);
          });
       } else if (type === 'adjustment') {
          doc.items.forEach((item: any) => {
             inventoryStore.updateProductStock(item.productId, item.quantity); // Signed quantity
          });
       } else if (type === 'count') {
          doc.items.forEach((item: any) => {
             if (item.diff !== undefined) {
               inventoryStore.updateProductStock(item.productId, item.diff); // Diff applied
             }
          });
       }
       // Note: Transfer logic assumes multi-warehouse which is simplified here to global stock for the demo context.
       // In a full implementation, `updateProductStock` would take a warehouseId.
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!systemStore.currentUser) return;
    salesStore.startShift({
      id: `sh-${Date.now()}`,
      userId: systemStore.currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open',
      cashTransactions: []
    });
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    salesStore.endShift(shiftId, {
      endTime: new Date().toISOString(),
      endCash,
      notes,
      status: 'Closed'
    });
  };

  const addCashTransaction = (type: 'in' | 'out', amount: number, reason: string) => {
    const activeShift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
    if (!activeShift) {
      alert("No active shift found. Please start a shift first.");
      return;
    }

    const txn: CashTransaction = {
      id: `ctx-${Date.now()}`,
      shiftId: activeShift.id,
      userId: systemStore.currentUser?.id || 'unknown',
      type,
      amount,
      reason,
      timestamp: new Date().toISOString()
    };

    salesStore.addCashTransaction(txn);

    // Log Audit
    systemStore.logAction({
      id: `aud-${Date.now()}`,
      action: type === 'in' ? 'CASH_IN' : 'CASH_OUT',
      details: `${type === 'in' ? 'Added' : 'Removed'} ${formatPrice(amount)}: ${reason}`,
      severity: 'medium',
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString(),
      resourceId: txn.id
    });
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     systemStore.addSyncLog({
        id: `sync-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: 'Simulated sync completed successfully.',
        durationMs: Math.floor(Math.random() * 1000) + 200
     });
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     const sale = salesStore.sales.find(s => s.id === saleId);
     if (sale) {
       salesStore.updateSale({
          ...sale,
          paymentStatus: 'paid',
          remainingAmount: 0,
          amountReceived: (sale.amountReceived || 0) + amount
       });
     }
  };

  // Automated Notification Logic (Example: Low Stock)
  useEffect(() => {
    const lowStockItems = inventoryStore.products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       const hasUnread = systemStore.notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          systemStore.addNotification({
             id: `notif-stock-${Date.now()}`,
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory',
             timestamp: new Date().toISOString(),
             read: false
          });
       }
    }
  }, [inventoryStore.products.length, systemStore.notifications.length]);

  const restoreSystemData = (data: any) => {
    systemStore.restoreSystemData(data);
    inventoryStore.restoreInventoryData(data);
    salesStore.restoreSalesData(data);
    stockStore.restoreStockData(data);
    systemStore.logAction({
      id: `aud-${Date.now()}`,
      action: 'SETTINGS_UPDATE',
      details: 'System data restored from backup',
      severity: 'high',
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString()
    });
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
    systemStore.addNotification({
      ...n,
      id: `notif-${Date.now()}`,
      timestamp: new Date().toISOString(),
      read: false
    });
  };

  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    systemStore.logAction({
      id: `aud-${Date.now()}`,
      action,
      details,
      severity,
      userId: systemStore.currentUser?.id || 'sys',
      userName: systemStore.currentUser?.name || 'System',
      timestamp: new Date().toISOString(),
      resourceId
    });
  };

  // --- Exposed Value ---
  const value: GlobalContextType = {
    // System
    currentUser: systemStore.currentUser,
    setCurrentUser: systemStore.setCurrentUser,
    users: systemStore.users,
    settings: systemStore.settings,
    branches: systemStore.branches,
    posMachines: systemStore.posMachines,
    auditLogs: systemStore.auditLogs,
    syncLogs: systemStore.syncLogs,
    notifications: systemStore.notifications,

    // Inventory
    products: inventoryStore.products,
    units: inventoryStore.units,
    categories: inventoryStore.categories,

    // Sales
    sales: salesStore.sales,
    customers: salesStore.customers,
    customerLevels: salesStore.customerLevels,
    shifts: salesStore.shifts,
    shiftSchedules: salesStore.shiftSchedules,
    promotions: salesStore.promotions,

    // Stock
    warehouses: stockStore.warehouses,
    locations: stockStore.locations,
    transfers: stockStore.transfers,
    counts: stockStore.counts,
    reservations: stockStore.reservations,
    receipts: stockStore.receipts,
    adjustments: stockStore.adjustments,

    isLoading,

    // Actions
    processSale,
    processReturn,

    addProduct: inventoryStore.addProduct,
    updateProduct: inventoryStore.updateProduct,
    deleteProduct: inventoryStore.deleteProduct,

    addUnit: inventoryStore.addUnit,
    updateUnit: inventoryStore.updateUnit,
    deleteUnit: inventoryStore.deleteUnit,

    addCategory: inventoryStore.addCategory,
    updateCategory: inventoryStore.updateCategory,
    deleteCategory: inventoryStore.deleteCategory,

    addBranch: systemStore.addBranch,
    updateBranch: systemStore.updateBranch,
    deleteBranch: systemStore.deleteBranch,

    addPos: systemStore.addPos,
    updatePos: systemStore.updatePos,
    deletePos: systemStore.deletePos,

    addWarehouse: stockStore.addWarehouse,
    updateWarehouse: stockStore.updateWarehouse,
    deleteWarehouse: stockStore.deleteWarehouse,

    addLocation: stockStore.addLocation,
    updateLocation: stockStore.updateLocation,
    deleteLocation: stockStore.deleteLocation,

    addUser: systemStore.addUser,
    updateUser: systemStore.updateUser,
    deleteUser: systemStore.deleteUser,

    addCustomer: salesStore.addCustomer,
    updateCustomer: salesStore.updateCustomer,
    deleteCustomer: salesStore.deleteCustomer,
    addCustomerLevel: salesStore.addCustomerLevel,
    updateCustomerLevel: salesStore.updateCustomerLevel,
    deleteCustomerLevel: salesStore.deleteCustomerLevel,

    updateTransfer: (t) => stockStore.updateDocument('transfers', t),
    deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),

    updateCount: (c) => stockStore.updateDocument('counts', c),
    deleteCount: (id) => stockStore.deleteDocument('counts', id),

    updateReservation: (r) => stockStore.updateDocument('reservations', r),
    deleteReservation: (id) => stockStore.deleteDocument('reservations', id),

    updateReceipt: (r) => stockStore.updateDocument('receipts', r),
    deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),

    updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
    deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),

    handleStockStatusChange,
    handleSyncOperation,

    startShift,
    endShift,
    addCashTransaction,
    addShiftSchedule: salesStore.addShiftSchedule,
    deleteShiftSchedule: salesStore.deleteShiftSchedule,

    addPromotion: salesStore.addPromotion,
    updatePromotion: salesStore.updatePromotion,
    deletePromotion: salesStore.deletePromotion,

    updateSettings: systemStore.updateSettings,

    settleSaleDebt,
    handleVoidSale,

    t,
    formatPrice,

    addNotification,
    markNotificationRead: systemStore.markNotificationRead,
    clearAllNotifications: systemStore.clearAllNotifications,

    restoreSystemData,
    logAction
  };

  return (
    <GlobalContext.Provider value={value}>
      {children}
    </GlobalContext.Provider>
  );
};

