  notes?: string;
}

export const ShiftManagement: React.FC<ShiftManagementProps> = ({
  shifts, branches, users, currentUser, onStartShift, onEndShift
}) => {
  const { 
    shiftSchedules, 
    addShiftSchedule, 
    deleteShiftSchedule, 
    settings, 
    posMachines, 
    sales, 
    formatPrice,
    addCashTransaction
  } = useGlobal();
  const [activeTab, setActiveTab] = useState<'attendance' | 'planning'>('attendance');

  // --- Attendance State ---
  const [startCash, setStartCash] = useState<string>('0');
  const [endCash, setEndCash] = useState<string>('0');
  const [notes, setNotes] = useState('');
  const [selectedBranchId, setSelectedBranchId] = useState<string>(currentUser?.branchId || '');
  const [confirmEnd, setConfirmEnd] = useState(false);

  // Cash Count Modal
  const [isCountModalOpen, setIsCountModalOpen] = useState(false);
  const [cashCounts, setCashCounts] = useState<Record<number, number>>({}); 

  // Cash Transaction Modal
  const [isTxnModalOpen, setIsTxnModalOpen] = useState(false);
  const [txnType, setTxnType] = useState<'in' | 'out'>('out');
  const [txnAmount, setTxnAmount] = useState('');
  const [txnReason, setTxnReason] = useState('');

  // Report State
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Auto-detect branch based on User or Device Settings
  useEffect(() => {
    if (currentUser?.branchId) {
      setSelectedBranchId(currentUser.branchId);
    } else if (settings.currentBranchId) {
      setSelectedBranchId(settings.currentBranchId);
    } else if (branches.length > 0) {
      setSelectedBranchId(branches[0].id);
    }
  }, [currentUser, settings, branches]);

  // Find active shift for current user
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');

  // Filter history (My shifts or all if admin/manager)
  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  // Filter schedules based on planning date
  const [planningDate, setPlanningDate] = useState(new Date().toISOString().split('T')[0]);
  const filteredSchedules = useMemo(() => {
    return shiftSchedules.filter(s => s.date === planningDate);
  }, [shiftSchedules, planningDate]);

  // Permissions
  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  // --- Report Logic ---
  const generateZReport = (shift: Shift) => {
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    // Filter sales during this shift
    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      // Ensure sale is within shift duration
      const inTimeRange = sDate >= start && sDate <= end;
      // Also ensure it's not voided
      return inTimeRange && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      const amount = s.total; // Or amountReceived if strict cash accounting
      salesByMethod[method] = (salesByMethod[method] || 0) + amount;
      totalSales += amount;
    });

    // Cash Transactions
    const txns = shift.cashTransactions || [];
    const cashIn = txns.filter(t => t.type === 'in').reduce((sum, t) => sum + t.amount, 0);
    const cashOut = txns.filter(t => t.type === 'out').reduce((sum, t) => sum + t.amount, 0);

    // Cash Logic: Opening + Cash Sales + PayIn - PayOut = Expected
    const cashSales = salesByMethod['cash'] || 0;
    const expectedCash = shift.startCash + cashSales + cashIn - cashOut;
    const actualEndCash = shift.endCash || 0; // 0 if still open/running view
    const discrepancy = actualEndCash - expectedCash;

    const report: ZReportData = {
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,
      expectedCash,
      discrepancy,
      transactionCount: shiftSales.length,
      cashIn,
      cashOut,
      notes: shift.notes
    };

    setViewingReport(report);
  };

  const handlePrintReport = () => {
    window.print();
  };

  // --- Handlers ---

  const handleStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBranchId) {
        alert("Please select a branch.");
        return;
    }
    onStartShift(selectedBranchId, parseFloat(startCash) || 0, notes);
    setStartCash('0');
    setNotes('');
  };

  const handleEnd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeShift) return;
    onEndShift(activeShift.id, parseFloat(endCash) || 0, notes);
    setEndCash('0');
    setNotes('');
    setConfirmEnd(false);
  };

  // --- Cash Transaction Handlers ---
  const openTxnModal = (type: 'in' | 'out') => {
    setTxnType(type);
    setTxnAmount('');
    setTxnReason('');
    setIsTxnModalOpen(true);
  };

  const submitCashTxn = (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(txnAmount);
    if (!amount || amount <= 0) {
      alert("Please enter a valid amount.");
      return;
    }
    if (!txnReason) {
      alert("Please enter a reason.");
      return;
    }
    addCashTransaction(txnType, amount, txnReason);
    setIsTxnModalOpen(false);
  };

  // --- Cash Count Logic ---
  const handleOpenCashCount = () => {
     const initialCounts: Record<number, number> = {};
     (settings.cashDenominations || []).forEach(d => initialCounts[d] = 0);
     setCashCounts(initialCounts);
     setIsCountModalOpen(true);
  };

  const handleUpdateCount = (denom: number, val: number) => {
     setCashCounts(prev => ({ ...prev, [denom]: val }));
  };

  const calculateCountTotal = () => {
     return Object.entries(cashCounts).reduce((acc, [denom, count]) => {
        return acc + (parseFloat(denom) * Number(count));
     }, 0);
  };

  const handleConfirmCount = () => {
     setEndCash(calculateCountTotal().toString());
     setIsCountModalOpen(false);
  };

  const currentBranchName = branches.find(b => b.id === selectedBranchId)?.name || 'Unknown Branch';
  const currentPosName = posMachines.find(p => p.id === settings.currentPosId)?.machineNumber || 'Unknown POS';
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Shift Management</h2>
          <p className="text-slate-500">Track working hours and manage staff schedules.</p>
        </div>

        {/* Tab Toggle */}
        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button
             onClick={() => setActiveTab('attendance')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
               activeTab === 'attendance' 
                 ? 'bg-white text-slate-800 shadow-sm' 
                 : 'text-slate-500 hover:text-slate-700'
             }`}
           >
             <Clock className="w-4 h-4 mr-2" />
             Time Clock
           </button>
           {canPlanShifts && (
             <button
               onClick={() => setActiveTab('planning')}
               className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                 activeTab === 'planning' 
                   ? 'bg-white text-slate-800 shadow-sm' 
                   : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <CalendarDays className="w-4 h-4 mr-2" />
               Roster / Planning
             </button>
           )}
        </div>
      </div>

      {activeTab === 'attendance' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in print:hidden">
          {/* Active Shift Card */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
             <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                <h3 className="font-bold text-slate-800 flex items-center">
                   <Clock className="w-5 h-5 mr-2 text-slate-500" />
                   Current Status
                </h3>
                {activeShift ? (
                   <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                      <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                      On Duty
                   </span>
                ) : (
                   <span className="px-3 py-1 bg-slate-200 text-slate-500 rounded-full text-xs font-bold uppercase tracking-wide">
                      Off Duty
                   </span>
                )}
             </div>

             <div className="p-6">
                {activeShift ? (
                   !confirmEnd ? (
                      <div className="space-y-6">
                         <div className="flex items-center justify-between">
                            <div>
                               <p className="text-sm text-slate-500 mb-1">Started At</p>
                               <p className="text-xl font-bold text-slate-800">
                                  {new Date(activeShift.startTime).toLocaleTimeString()}
                               </p>
                               <p className="text-xs text-slate-400">
                                  {new Date(activeShift.startTime).toLocaleDateString()}
                               </p>
                            </div>
                            <div>
                               <p className="text-sm text-slate-500 mb-1">Opening Cash</p>
                               <p className="text-xl font-bold text-green-600">
                                  {formatPrice(activeShift.startCash)}
                               </p>
                            </div>
                         </div>

                         {/* Cash Drawer Operations Section */}
                         <div className="p-4 bg-slate-50 rounded-xl border border-slate-200">
                            <h4 className="font-bold text-slate-700 mb-3 flex items-center text-sm">
                               <Briefcase className="w-4 h-4 mr-2" /> Drawer Operations
                            </h4>
                            <div className="grid grid-cols-2 gap-3">
                               <button 
                                  onClick={() => openTxnModal('in')}
                                  className="flex items-center justify-center px-4 py-2 bg-white border border-green-200 text-green-700 rounded-lg hover:bg-green-50 transition-colors font-medium text-sm shadow-sm"
                               >
                                  <ArrowDownCircle className="w-4 h-4 mr-2" />
                                  Add Cash (Pay In)
                               </button>
                               <button 
                                  onClick={() => openTxnModal('out')}
                                  className="flex items-center justify-center px-4 py-2 bg-white border border-red-200 text-red-700 rounded-lg hover:bg-red-50 transition-colors font-medium text-sm shadow-sm"
                               >
                                  <ArrowUpCircle className="w-4 h-4 mr-2" />
                                  Remove Cash (Pay Out)
                               </button>
                            </div>
                            {activeShift.cashTransactions && activeShift.cashTransactions.length > 0 && (
                               <div className="mt-3 pt-3 border-t border-slate-200">
                                  <p className="text-xs text-slate-500 font-bold mb-1">Recent Movements:</p>
                                  <ul className="space-y-1">
                                     {activeShift.cashTransactions.slice(-3).map(txn => (
                                        <li key={txn.id} className="text-xs flex justify-between items-center text-slate-600">
                                           <span>{txn.reason}</span>
                                           <span className={`font-mono font-bold ${txn.type === 'in' ? 'text-green-600' : 'text-red-600'}`}>
                                              {txn.type === 'in' ? '+' : '-'}{formatPrice(txn.amount)}
                                           </span>
                                        </li>
                                     ))}
                                  </ul>
                               </div>
                            )}
                         </div>

                         <div className="flex gap-3">
                            <button 
                               onClick={() => generateZReport(activeShift)}
                               className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm flex items-center justify-center"
                            >
                               <FileText className="w-5 h-5 mr-2" />
                               X-Report (Draft)
                            </button>
                            <button 
                                onClick={() => setConfirmEnd(true)}
                                className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold hover:bg-red-700 transition-colors shadow-lg flex items-center justify-center"
                            >
                                <StopCircle className="w-6 h-6 mr-2" />
                                End Shift
                            </button>
                         </div>
                      </div>
                   ) : (
                      <form onSubmit={handleEnd} className="space-y-4 animate-fade-in">
                         <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                            <h4 className="font-bold text-slate-700 mb-2">Closing Register</h4>
                            <p className="text-xs text-slate-500">Please count the cash drawer and enter the total amount.</p>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Closing Cash Amount</label>
                            <div className="flex gap-2">
                               <div className="relative flex-1">
                                  <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                                  <input 
                                     type="number" 
                                     step="0.01" 
                                     min="0"
                                     required
                                     value={endCash}
                                     onChange={(e) => setEndCash(e.target.value)}
                                     className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 text-lg font-bold"
                                  />
                               </div>
                               <button 
                                  type="button" 
                                  onClick={handleOpenCashCount}
                                  className="px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors flex items-center shadow-sm font-medium whitespace-nowrap"
                               >
                                  <Calculator className="w-5 h-5 mr-2" /> Count
                               </button>
                            </div>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Shift Notes</label>
                            <textarea 
                               value={notes}
                               onChange={(e) => setNotes(e.target.value)}
                               className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 h-24 resize-none"
                               placeholder="Any discrepancies or comments..."
                            />
                         </div>

                         <div className="flex space-x-3 pt-2">
                            <button 
                               type="button"
                               onClick={() => setConfirmEnd(false)}
                               className="flex-1 py-3 border border-slate-300 text-slate-600 rounded-lg font-medium hover:bg-slate-50"
                            >
                               Cancel
                            </button>
                            <button 
                               type="submit"
                               className="flex-1 py-3 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md"
                            >
                               Confirm Clock Out
                            </button>
                         </div>
                      </form>
                   )
                ) : (
                   <form onSubmit={handleStart} className="space-y-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Location / Branch</label>
                         <div className="relative">
                            <MapPin className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                            <input 
                               type="text" 
                               disabled
                               value={currentBranchName}
                               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg bg-slate-100 text-slate-500 font-medium cursor-not-allowed"
                            />
                         </div>
                         <div className="mt-2 flex items-center text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-200">
                            <Monitor className="w-3.5 h-3.5 mr-2 text-blue-500" />
                            <span>
                               Configured Device: <span className="font-semibold text-slate-700">{currentPosName}</span>
                            </span>
                         </div>
                      </div>

                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Opening Cash Amount</label>
                         <div className="relative">
                            <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                            <input 
                               type="number" 
                               step="0.01" 
                               min="0"
                               required
                               value={startCash}
                               onChange={(e) => setStartCash(e.target.value)}
                               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 font-bold"
                            />
                         </div>
                      </div>

                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Notes (Optional)</label>
                         <textarea 
                            value={notes}
                            onChange={(e) => setNotes(e.target.value)}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 h-20 resize-none"
                            placeholder="e.g. Register 2"
                         />
                      </div>

                      <button 
                         type="submit"
                         className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg flex items-center justify-center"
                      >
                         <PlayCircle className="w-6 h-6 mr-2" />
                         Start Shift (Clock In)
                      </button>
                   </form>
                )}
             </div>
          </div>

          {/* Recent History */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden h-[500px]">
             <div className="p-4 border-b border-slate-100 bg-slate-50">
                <h3 className="font-bold text-slate-700 flex items-center">
                   <History className="w-5 h-5 mr-2 text-slate-500" />
                   Recent Shift History
                </h3>
             </div>
             <div className="overflow-y-auto flex-1 p-0">
                {historyShifts.length === 0 ? (
                   <div className="p-8 text-center text-slate-400">No shift history found.</div>
                ) : (
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold sticky top-0">
                         <tr>
                            <th className="px-4 py-3">Date / User</th>
                            <th className="px-4 py-3">Duration</th>
                            <th className="px-4 py-3 text-right">Cash Out</th>
                            <th className="px-4 py-3 text-center">Action</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {historyShifts.map(shift => {
                            const start = new Date(shift.startTime);
                            const end = shift.endTime ? new Date(shift.endTime) : null;
                            const duration = end ? 
                               Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60) * 10) / 10 + ' hrs' : 
                               'Running';

                            const user = users.find(u => u.id === shift.userId);
                            const branch = branches.find(b => b.id === shift.branchId);

                            return (
                               <tr key={shift.id} className="hover:bg-slate-50 transition-colors text-sm">
                                  <td className="px-4 py-3">
                                     <div className="font-medium text-slate-800">{start.toLocaleDateString()}</div>
                                     <div className="text-xs text-slate-500">{user?.name || 'Unknown'}</div>
                                     <div className="text-[10px] text-slate-400">{branch?.name}</div>
                                  </td>
                                  <td className="px-4 py-3 text-slate-600">
                                     {start.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} - 
                                     {end ? end.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : '...'}
                                     <div className="text-xs text-slate-400 mt-0.5">{duration}</div>
                                  </td>
                                  <td className="px-4 py-3 text-right font-mono">
                                     {shift.endCash !== undefined ? formatPrice(shift.endCash) : '-'}
                                  </td>
                                  <td className="px-4 py-3 text-center">
                                     <button 
                                        onClick={() => generateZReport(shift)}
                                        className="text-blue-600 hover:text-blue-800 text-xs font-bold underline"
                                     >
                                        Report
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                )}
             </div>
          </div>
        </div>
      )}

      {/* Cash Transaction Modal */}
      {isTxnModalOpen && (
         <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
               <div className={`p-4 border-b flex justify-between items-center ${txnType === 'in' ? 'bg-green-50 border-green-100' : 'bg-red-50 border-red-100'}`}>
                  <h3 className={`font-bold flex items-center ${txnType === 'in' ? 'text-green-800' : 'text-red-800'}`}>
                     {txnType === 'in' ? <ArrowDownCircle className="w-5 h-5 mr-2" /> : <ArrowUpCircle className="w-5 h-5 mr-2" />}
                     {txnType === 'in' ? 'Pay In (Add Cash)' : 'Pay Out (Remove Cash)'}
                  </h3>
                  <button onClick={() => setIsTxnModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
               </div>

               <form onSubmit={submitCashTxn} className="p-6 space-y-4">
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Amount</label>
                     <div className="relative">
                        <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                        <input 
                           type="number" 
                           step="0.01" 
                           min="0"
                           required
                           value={txnAmount}
                           onChange={(e) => setTxnAmount(e.target.value)}
                           className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 font-bold text-lg"
                           autoFocus
                        />
                     </div>
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                     <input 
                        type="text" 
                        required
                        value={txnReason}
                        onChange={(e) => setTxnReason(e.target.value)}
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        placeholder={txnType === 'in' ? 'e.g. Change replenishment' : 'e.g. Lunch for staff, Vendor payment'}
                     />
                  </div>
                  <button 
                     type="submit"
                     className={`w-full py-3 rounded-lg font-bold text-white shadow-md transition-colors ${txnType === 'in' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}`}
                  >
                     Confirm Transaction
                  </button>
               </form>
            </div>
         </div>
      )}

      {/* Cash Counter Modal */}
      {isCountModalOpen && (
         <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[70] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md max-h-[90vh] flex flex-col overflow-hidden">
               <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <h3 className="font-bold text-slate-800 flex items-center">
                     <Calculator className="w-5 h-5 mr-2 text-slate-500" /> Cash Drawer Counter
                  </h3>
                  <button onClick={() => setIsCountModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-6 h-6" />
                  </button>
               </div>

               <div className="flex-1 overflow-y-auto p-6 space-y-4">
                  {(settings.cashDenominations && settings.cashDenominations.length > 0 ? settings.cashDenominations : [1000, 500, 100, 50, 20, 10, 5, 1]).map(denom => (
                     <div key={denom} className="flex items-center justify-between">
                        <span className="font-bold text-slate-700 w-24 text-right pr-4">{formatPrice(denom)}</span>
                        <span className="text-slate-400 mx-2">x</span>
                        <input 
                           type="number" 
                           min="0"
                           className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-center font-medium focus:ring-2 focus:ring-primary-500"
                           value={cashCounts[denom] || ''}
                           onChange={(e) => handleUpdateCount(denom, parseInt(e.target.value) || 0)}
                           placeholder="0"
                        />
                        <span className="text-slate-800 font-bold w-28 text-right">
                           = {formatPrice(denom * (cashCounts[denom] || 0))}
                        </span>
                     </div>
                  ))}
               </div>

               <div className="p-4 border-t border-slate-100 bg-slate-50">
                  <div className="flex justify-between items-center mb-4">
                     <span className="text-lg font-bold text-slate-700">Total Counted</span>
                     <span className="text-2xl font-bold text-green-600">{formatPrice(calculateCountTotal())}</span>
                  </div>
                  <button 
                     onClick={handleConfirmCount}
                     className="w-full py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 shadow-md transition-colors"
                  >
                     Confirm & Use Total
                  </button>
               </div>
            </div>
         </div>
      )}

      {/* Viewing Report Modal */}
      {viewingReport && (
         <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[60] p-4 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">
               <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden">
                  <h3 className="font-bold text-slate-800">Shift Report (Z-Report)</h3>
                  <button onClick={() => setViewingReport(null)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-6 h-6" />
                  </button>
               </div>

               <div className="flex-1 overflow-y-auto p-6 bg-slate-50 print:p-0 print:overflow-visible">
                  {/* PRINTABLE SECTION */}
                  <div 
                    id="printable-receipt" 
                    className={`bg-white p-6 shadow-sm border border-slate-200 text-sm font-mono text-slate-700 mx-auto ${receiptWidthClass} print:shadow-none print:border-none print:mx-0`}
                  >
                     <div className="text-center mb-4">
                        <h2 className="text-lg font-bold text-slate-900 mb-1">{settings.companyName}</h2>
                        <p className="font-bold">{viewingReport.branch}</p>
                        <p className="text-xs text-slate-500 mt-1 uppercase">Z-REPORT / END OF SHIFT</p>
                        <p className="mt-2 text-xs">Print: {new Date().toLocaleString()}</p>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-1">
                        <div className="flex justify-between"><span>Shift ID:</span><span>{viewingReport.shiftId.slice(-6)}</span></div>
                        <div className="flex justify-between"><span>User:</span><span>{viewingReport.user}</span></div>
                        <div className="flex justify-between"><span>Start:</span><span>{viewingReport.start}</span></div>
                        <div className="flex justify-between"><span>End:</span><span>{viewingReport.end}</span></div>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-2">
                        <div className="flex justify-between font-bold">
                           <span>Total Sales</span>
                           <span>{formatPrice(viewingReport.totalSales)}</span>
                        </div>
                        <div className="text-xs text-slate-500 pl-2 space-y-1">
                           {Object.entries(viewingReport.salesByMethod).map(([method, amount]) => (
                              <div key={method} className="flex justify-between">
                                 <span className="capitalize">{method}</span>
                                 <span>{formatPrice(amount)}</span>
                              </div>
                           ))}
                        </div>
                        <div className="flex justify-between text-xs mt-1">
                           <span>Transactions</span>
                           <span>{viewingReport.transactionCount}</span>
                        </div>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-2">
                        <div className="flex justify-between">
                           <span>Opening Cash</span>
                           <span>{formatPrice(viewingReport.startCash)}</span>
                        </div>
                        <div className="flex justify-between">
                           <span>Cash Sales</span>
                           <span>{formatPrice(viewingReport.salesByMethod['cash'] || 0)}</span>
                        </div>

                        {viewingReport.cashIn > 0 && (
                           <div className="flex justify-between text-green-600">
                              <span>+ Pay Ins</span>
                              <span>{formatPrice(viewingReport.cashIn)}</span>
                           </div>
                        )}
                        {viewingReport.cashOut > 0 && (
                           <div className="flex justify-between text-red-600">
                              <span>- Pay Outs</span>
                              <span>{formatPrice(viewingReport.cashOut)}</span>
                           </div>
                        )}

                        <div className="flex justify-between font-bold border-t border-slate-100 pt-1 mt-1">
                           <span>Expected Cash</span>
                           <span>{formatPrice(viewingReport.expectedCash)}</span>
                        </div>
                        <div className="flex justify-between font-bold text-slate-900">
                           <span>Actual Count</span>
                           <span>{formatPrice(viewingReport.endCash)}</span>
                        </div>

                        {viewingReport.discrepancy !== 0 && (
                           <div className={`flex justify-between font-bold pt-1 ${viewingReport.discrepancy < 0 ? 'text-red-600' : 'text-green-600'}`}>
                              <span>Variance</span>
                              <span>{formatPrice(viewingReport.discrepancy)}</span>
                           </div>
                        )}
                     </div>

                     {viewingReport.notes && (
                        <div className="mt-4 border-t border-dashed border-slate-300 pt-2">
                           <p className="text-xs font-bold mb-1">Notes:</p>
                           <p className="text-xs italic">{viewingReport.notes}</p>
                        </div>
                     )}

                     <div className="mt-8 pt-4 border-t border-slate-300 text-center text-xs">
                        <p>_______________________</p>
                        <p className="mt-1">Manager Signature</p>
                     </div>
                  </div>
               </div>

               <div className="p-4 border-t border-slate-100 flex justify-end bg-white print:hidden">
                  <button 
                     onClick={handlePrintReport}
                     className="px-6 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 flex items-center font-bold shadow-sm"
                  >
                     <Printer className="w-4 h-4 mr-2" /> Print Report
                  </button>
               </div>
            </div>
         </div>
      )}

      {/* (Planning Tab logic remains same as previous version, omitted for brevity as unchanged) */}
      {activeTab === 'planning' && canPlanShifts && (
        <div className="flex flex-col lg:flex-row gap-6 animate-fade-in h-full print:hidden">
           {/* Schedule List */}
           <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
              <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                 <h3 className="font-bold text-slate-700 flex items-center">
                    <List className="w-5 h-5 mr-2 text-slate-500" />
                    Shift Roster for {new Date(planningDate).toLocaleDateString()}
                 </h3>
                 <span className="bg-slate-200 text-slate-600 px-2 py-1 rounded text-xs font-bold">
                    {filteredSchedules.length} Shifts
                 </span>
              </div>
              <div className="overflow-y-auto flex-1 p-4 space-y-3">
                 {filteredSchedules.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                       <Calendar className="w-12 h-12 mb-3 opacity-30" />
                       <p>No shifts assigned for this date.</p>
                    </div>
                 ) : (
                    filteredSchedules.map(schedule => {
                       const user = users.find(u => u.id === schedule.userId);
                       const branch = branches.find(b => b.id === schedule.branchId);

                       return (
                          <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group">
                             <div className="flex items-center space-x-4">
                                <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                                   {user?.name.charAt(0) || 'U'}
                                </div>
                                <div>
                                   <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                                   <div className="flex items-center text-xs text-slate-500 mt-1">
                                      <span className="flex items-center mr-3">
                                         <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                                      </span>
                                      <span className="flex items-center">
                                         <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                                      </span>
                                   </div>
                                </div>
                             </div>

                             <button 
                                onClick={() => deleteShiftSchedule(schedule.id)}
                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                             >
                                <Trash2 className="w-4 h-4" />
                             </button>
                          </div>
                       );
                    })
                 )}
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, Warehouse, InventoryAnalysisResult, Sale, Branch } from '../types';
import { Search, Plus, Edit2, Trash2, X, Check, Layers, Box, ArrowRight, ArrowLeftRight, RefreshCw, Info, Building2, AlertTriangle, Bell, Sparkles, Loader2, TrendingUp, AlertCircle, PackagePlus, Scale, DollarSign, Store, ChevronLeft, ChevronRight, ShoppingBag, Image as ImageIcon, Upload, Palette, Ruler, ScanBarcode, Printer, Tag, Download, FileSpreadsheet } from 'lucide-react';
import { analyzeInventory } from '../services/geminiService';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
// Direct Store Access
import { useInventoryStore } from '../store/useInventoryStore';

interface InventoryProps {
  // Keeping props for compatibility if passed from parent, but prioritizing internal store if available
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const Inventory: React.FC<InventoryProps> = ({ 
  // We accept props but also use the store directly for optimized updates
  warehouses = [], 
  sales 
}) => {
  const { settings, t, formatPrice } = useGlobal();

  // Use specific selectors to avoid re-rendering on unrelated changes
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = settings.defaultItemsPerPage || 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<InventoryAnalysisResult | null>(null);

  // Scanner State
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  // Label Printing State
  const [isLabelModalOpen, setIsLabelModalOpen] = useState(false);
  const [labelProduct, setLabelProduct] = useState<Product | null>(null);
  const [labelSettings, setLabelSettings] = useState({
     type: 'shelf' as 'shelf' | 'sticker',
     quantity: 1,
     showPrice: true,
     showSku: true,
     showUnit: true
  });

  // Import State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importPreview, setImportPreview] = useState<any[]>([]);
  const [importStats, setImportStats] = useState({ new: 0, update: 0, error: 0 });
  const importFileRef = useRef<HTMLInputElement>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    sku: '',
    barcode: '',
    category: '',
    price: 0,
    costPrice: 0,
    stock: 0,
    minStock: 20,
    unit: '',
    physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [],
    imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  const getFlattenedCategories = () => {
    const options: { id: string; name: string; level: number }[] = [];
    const buildOptions = (parentId: string | null, level: number) => {
      const children = categories.filter(c => c.parentId === parentId);
      children.forEach(c => {
        options.push({ id: c.id, name: c.name, level });
        buildOptions(c.id, level + 1);
      });
    };
    buildOptions(null, 0);
    return options;
  };

  const categoryOptions = getFlattenedCategories();

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower) ||
      (p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      ));

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setActiveTab('general');
    setFormData({
      name: '',
      sku: '',
      barcode: '',
      category: categoryOptions[0]?.id || '',
      price: 0,
      costPrice: 0,
      stock: 0,
      minStock: 20,
      unit: units[0]?.symbol || 'pc',
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (product: Product) => {
    setEditingId(product.id);
    setActiveTab('general');
    setFormData({
      name: product.name,
      sku: product.sku,
      barcode: product.barcode,
      category: product.category,
      price: product.price,
      costPrice: product.costPrice || 0,
      stock: product.stock,
      minStock: product.minStock || 20,
      unit: product.unit,
      physical: product.physical || { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: product.branchPrices || [],
      imageUrl: product.imageUrl || ''
    });
    setVariants(product.variants ? product.variants.map(v => ({...v})) : []);
    setIsModalOpen(true);
  };

  const handleOpenLabelModal = (product: Product) => {
     setLabelProduct(product);
     setLabelSettings({
        type: 'shelf',
        quantity: 1,
        showPrice: true,
        showSku: true,
        showUnit: true
     });
     setIsLabelModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  useEffect(() => {
    if (isAiModalOpen && !aiResult && !aiLoading) {
      const performAnalysis = async () => {
        setAiLoading(true);
        const result = await analyzeInventory(products, sales);
        setAiResult(result);
        setAiLoading(false);
      };
      performAnalysis();
    }
  }, [isAiModalOpen, products, sales, aiResult, aiLoading]);

  const handleOpenAiInsights = () => setIsAiModalOpen(true);

  // ... (handleInputChange, handlePhysicalChange, variants logic remain same)
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({
      ...prev,
      [name]: isNum ? (parseFloat(value) || 0) : value
    }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      physical: {
        ...prev.physical,
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const generateVariantCodes = (index: number) => {
    const suffix = (index + 1).toString().padStart(3, '0');
    const skuBase = formData.sku || 'SKU';
    return { code: `${skuBase}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '' };
  };

  const handleAddVariant = () => {
    const { code, barcode } = generateVariantCodes(variants.length);
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', 
      code,
      barcode,
      conversionFactor: 1, 
      price: formData.price,
      costPrice: formData.costPrice,
      color: '',
      size: ''
    }]);
  };

  const handleRemoveVariant = (index: number) => setVariants(prev => prev.filter((_, i) => i !== index));

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVariants = [...prev];
      let updatedVariant = { ...newVariants[index], [field]: value };

      if (field === 'name') {
        const mainUnitDef = units.find(u => u.symbol === formData.unit);
        const variantUnitDef = units.find(u => u.symbol === value);
        if (mainUnitDef && variantUnitDef && mainUnitDef.category === variantUnitDef.category) {
          const factor = mainUnitDef.baseFactor / variantUnitDef.baseFactor;
          updatedVariant.conversionFactor = factor;
          updatedVariant.price = (formData.price || 0) / factor;
          updatedVariant.costPrice = (formData.costPrice || 0) / factor;
        }
      }
      if (field === 'price' || field === 'costPrice' || field === 'conversionFactor') {
        updatedVariant[field] = parseFloat(value) || 0;
      }
      newVariants[index] = updatedVariant;
      return newVariants;
    });
  };

  const handleVariantRelationChange = (index: number, ratio: number, mode: 'sub' | 'bundle') => {
    const factor = mode === 'sub' ? ratio : (1 / ratio);
    setVariants(prev => {
      const newVariants = [...prev];
      newVariants[index] = { 
        ...newVariants[index], 
        conversionFactor: factor,
        price: factor !== 0 ? ((formData.price || 0) / factor) : 0,
        costPrice: factor !== 0 ? ((formData.costPrice || 0) / factor) : 0
      };
      return newVariants;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        id: editingId || `P-${Date.now()}`,
        name: formData.name!,
        category: formData.category || 'Uncategorized',
        price: formData.price || 0,
        costPrice: formData.costPrice || 0,
        stock: formData.stock || 0,
        minStock: formData.minStock || 20,
        unit: formData.unit!,
        sku: formData.sku || '',
        barcode: formData.barcode || '',
        physical: formData.physical,
        branchPrices: formData.branchPrices,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: editingId 
          ? products.find(p => p.id === editingId)?.warehouseInventory 
          : [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
        imageUrl: formData.imageUrl
      };

      if (editingId) updateProduct(productData);
      else addProduct(productData);
      setIsModalOpen(false);
    }
  };

  const handleScan = (code: string) => {
    setSearchTerm(code);
    setIsScannerOpen(false);
  };

  const handlePrintLabel = () => {
     window.print();
  };

  // --- CSV Export Logic ---
  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'CostPrice', 'Stock', 'MinStock', 'Unit', 'SKU', 'Barcode'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => {
        const catName = getCategoryName(p.category);
        // Escape quotes for CSV safety
        const safeName = `"${p.name.replace(/"/g, '""')}"`;
        const safeCat = `"${catName.replace(/"/g, '""')}"`;
        return [
          p.id,
          safeName,
          safeCat,
          p.price,
          p.costPrice || 0,
          p.stock,
          p.minStock,
          p.unit,
          p.sku,
          p.barcode
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `inventory_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- CSV Import Logic ---
  const handleImportClick = () => {
    importFileRef.current?.click();
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      const lines = text.split('\n');
      // Simple CSV parse
      const newProducts: any[] = [];
      let newCount = 0;
      let updateCount = 0;
      let errorCount = 0;

      for (let i = 1; i < lines.length; i++) {
        if (!lines[i].trim()) continue;

        const row = lines[i].match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
        if (!row) { errorCount++; continue; }

        // Map based on assumed order: ID, Name, Category, Price, Cost, Stock, Min, Unit, SKU, Barcode
        const p: any = {};
        p.id = row[0]?.replace(/"/g, ''); // ID
        p.name = row[1]?.replace(/"/g, '');
        p.category = row[2]?.replace(/"/g, ''); 
        p.price = parseFloat(row[3]) || 0;
        p.costPrice = parseFloat(row[4]) || 0;
        p.stock = parseFloat(row[5]) || 0;
        p.minStock = parseFloat(row[6]) || 0;
        p.unit = row[7]?.replace(/"/g, '') || 'pc';
        p.sku = row[8]?.replace(/"/g, '') || '';
        p.barcode = row[9]?.replace(/"/g, '') || '';

        // Check if ID exists to update, else new
        const exists = products.find(prod => prod.id === p.id || prod.sku === p.sku);
        if (exists) {
           p.action = 'Update';
           p.existingId = exists.id;
           updateCount++;
        } else {
           p.action = 'Create';
           newCount++;
        }
        newProducts.push(p);
      }

      setImportPreview(newProducts);
      setImportStats({ new: newCount, update: updateCount, error: errorCount });
      setIsImportModalOpen(true);
      if (importFileRef.current) importFileRef.current.value = ''; // Reset
    };
    reader.readAsText(file);
