           {paginatedProducts.map((product) => {
              const isLowStock = product.stock < (product.minStock || 20);
              return (
                 <div 
                    key={product.id}
                    className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative"
                 >
                    {isLowStock && <div className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-bl-lg z-10" />}

                    <div className="flex p-3 gap-3">
                       {/* Image */}
                       <div className="w-20 h-20 bg-slate-100 rounded-lg flex-shrink-0 overflow-hidden border border-slate-100">
                          {product.imageUrl ? (
                             <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                          ) : (
                             <div className="w-full h-full flex items-center justify-center text-slate-300">
                                <Box className="w-8 h-8" />
                             </div>
                          )}
                       </div>

                       {/* Content */}
                       <div className="flex-1 min-w-0 flex flex-col justify-between">
                          <div>
                             <h3 className="font-bold text-slate-800 text-sm truncate">{product.name}</h3>
                             <p className="text-xs text-slate-500 truncate">{getCategoryName(product.category)}</p>
                             <div className="flex items-center gap-2 mt-1">
                                <span className="text-xs font-mono bg-slate-100 px-1.5 rounded text-slate-600">{product.sku}</span>
                                {product.variants && product.variants.length > 0 && (
                                   <span className="text-[10px] bg-orange-100 text-orange-700 px-1.5 rounded font-bold">
                                      {product.variants.length} Variants
