                            type="text"
                            name="name"
                            required
                            value={formData.name}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.category')} *</label>
                          <select
                            name="category"
                            required
                            value={formData.category}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                          >
                             <option value="">Select</option>
                             {categoryOptions.map(cat => (
                               <option key={cat.id} value={cat.id}>
                                  {'\u00A0'.repeat(cat.level * 3)}{cat.name}
                               </option>
                             ))}
                          </select>
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.sku')}</label>
                           <input
                            type="text"
                            name="sku"
                            value={formData.sku}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Barcode</label>
                           <input
                            type="text"
                            name="barcode"
                            value={formData.barcode}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.stock')}</label>
                           <input
                            type="number"
                            name="stock"
                            min="0"
                            value={formData.stock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Min Stock</label>
                           <input
                            type="number"
                            name="minStock"
                            min="0"
                            value={formData.minStock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Unit</label>
                           <select
                              name="unit"
                              required
                              value={formData.unit}
                              onChange={handleInputChange}
                              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                           >
                              <option value="">Select</option>
                              {units.map(u => (
                                 <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                              ))}
                           </select>
                        </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'physical' && (
                 <div className="space-y-6 animate-fade-in">
                    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                       <h4 className="font-bold text-slate-800 mb-4 flex items-center"><Ruler className="w-5 h-5 mr-2" /> Dimensions & Weight</h4>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                             <label className="block text-sm font-medium text-slate-700 mb-1">Weight (kg)</label>
                             <input type="number" value={formData.physical?.weight || 0} onChange={e => handlePhysicalChange('weight', e.target.value)} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                          </div>
                          <div className="grid grid-cols-3 gap-2">
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Length (cm)</label>
                                <input type="number" value={formData.physical?.depth || 0} onChange={e => handlePhysicalChange('depth', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Width (cm)</label>
                                <input type="number" value={formData.physical?.width || 0} onChange={e => handlePhysicalChange('width', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Height (cm)</label>
                                <input type="number" value={formData.physical?.height || 0} onChange={e => handlePhysicalChange('height', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                          </div>
                       </div>
                    </div>
                 </div>
              )}

              {activeTab === 'pricing' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div>
                            <label className="block text-sm font-bold text-slate-800 mb-2">{t('inventory.price')} (Selling Price)</label>
                            <div className="relative">
                               <span className="absolute left-3 top-2.5 text-slate-400 font-bold">{settings.currencySymbol}</span>
                               <input
                                 type="number"
                                 name="price"
                                 required
                                 min="0"
                                 step="0.01"
                                 value={formData.price}
                                 onChange={handleInputChange}
                                 className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-bold text-slate-800"
                               />
                            </div>
                         </div>
                         <div>
                            <label className="block text-sm font-bold text-slate-800 mb-2">Cost Price (For Profit Calc)</label>
                            <div className="relative">
                               <span className="absolute left-3 top-2.5 text-slate-400 font-bold">{settings.currencySymbol}</span>
                               <input
                                 type="number"
                                 name="costPrice"
                                 min="0"
                                 step="0.01"
                                 value={formData.costPrice}
                                 onChange={handleInputChange}
                                 className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-medium text-slate-600"
                               />
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'variants' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="flex justify-between items-center mb-4">
                        <h4 className="font-bold text-slate-800">Product Variants</h4>
                        <button 
                          type="button" 
                          onClick={handleAddVariant}
                          className="text-sm flex items-center text-primary-600 font-medium hover:text-primary-700 bg-primary-50 px-3 py-1.5 rounded-lg transition-colors"
                        >
                          <Plus className="w-4 h-4 mr-1" /> {t('common.add')} Variant
                        </button>
                      </div>

                      {variants.length === 0 ? (
                        <div className="text-center py-8 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">
                          No variants added.
                        </div>
                      ) : (
                        <div className="space-y-4">
                           {variants.map((variant, index) => {
                              const factor = variant.conversionFactor || 1;
                              const isBundle = factor > 0 && factor < 1;
                              const displayRatio = isBundle ? Math.round(1/factor) : factor;

                              return (
                                <div key={index} className="bg-slate-50 p-4 rounded-xl border border-slate-200 relative group">
                                   <button 
                                      type="button"
                                      onClick={() => handleRemoveVariant(index)}
                                      className="absolute top-2 right-2 p-1 text-slate-400 hover:text-red-50 opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                      <Trash2 className="w-4 h-4" />
                                    </button>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Variant Unit</label>
                                          <select
                                            value={variant.name}
                                            onChange={e => handleVariantChange(index, 'name', e.target.value)}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white"
                                          >
                                            <option value="">Select</option>
                                            {Object.entries(unitsByCategory).map(([cat, catUnits]) => (
                                              <optgroup key={cat} label={cat}>
                                                {(catUnits as UnitDefinition[]).map(u => (
                                                  <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                                                ))}
                                              </optgroup>
                                            ))}
                                          </select>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Code / SKU</label>
                                          <input type="text" value={variant.code} onChange={e => handleVariantChange(index, 'code', e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white font-mono" />
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Color (Hex)</label>
                                          <div className="flex items-center">
                                             <input type="color" value={variant.color || '#000000'} onChange={e => handleVariantChange(index, 'color', e.target.value)} className="h-8 w-8 mr-2 p-0 border-0 rounded overflow-hidden" />
                                             <input type="text" value={variant.color || ''} onChange={e => handleVariantChange(index, 'color', e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white" placeholder="#RRGGBB" />
                                          </div>
                                       </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                                       <div className="bg-white p-2 rounded border border-slate-200 flex items-center text-sm">
                                          <span className="text-slate-500 mr-2 text-xs uppercase font-bold">Ratio:</span>
                                          <select
                                              value={isBundle ? 'bundle' : 'sub'}
                                              onChange={(e) => handleVariantRelationChange(index, displayRatio, e.target.value as 'bundle' | 'sub')}
                                              className="px-2 py-1 text-xs border rounded bg-slate-50 mr-2"
                                            >
                                              <option value="sub">Sub-unit</option>
                                              <option value="bundle">Bundle</option>
                                            </select>
                                            <input 
                                              type="number" 
                                              min="1"
                                              value={displayRatio}
                                              onChange={(e) => handleVariantRelationChange(index, parseFloat(e.target.value) || 1, isBundle ? 'bundle' : 'sub')}
                                              className="w-16 px-1 py-0.5 border rounded text-center font-bold mx-1"
                                            />
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Selling Price</label>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">{settings.currencySymbol}</span>
                                            <input
                                              type="number"
                                              value={variant.price}
                                              onChange={e => handleVariantChange(index, 'price', e.target.value)}
                                              className="w-full pl-6 px-3 py-1.5 border border-slate-300 rounded text-sm font-bold text-slate-700"
                                              placeholder="Price"
                                            />
                                          </div>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Cost Price</label>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">{settings.currencySymbol}</span>
                                            <input
                                              type="number"
                                              value={variant.costPrice || 0}
                                              onChange={e => handleVariantChange(index, 'costPrice', e.target.value)}
                                              className="w-full pl-6 px-3 py-1.5 border border-slate-300 rounded text-sm font-medium text-slate-600"
                                              placeholder="Cost"
                                            />
                                          </div>
                                       </div>
                                    </div>
                                </div>
                              );
                           })}
                        </div>
                      )}
                   </div>
                </div>
              )}

            </form>

            <div className="p-4 border-t border-slate-100 flex justify-end items-center bg-white shrink-0 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  {t('common.cancel')}
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {t('common.save')}
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
